package rgexport

const (
	resourcesPath = "/providers/Microsoft.ResourceGraph/resources"
	apiVersion    = "2024-04-01"

	// resultFormatObjectArray pins rows to JSON objects; the service also
	// offers "table", which this client never requests.
	resultFormatObjectArray = "objectArray"

	// resultTruncated is a string enum on the wire ("true"/"false"),
	// not a JSON boolean.
	resultTruncatedTrue = "true"
)

// queryRequest is the QueryRequest body of the Resources operation.
type queryRequest struct {
	Query         string        `json:"query"`
	Subscriptions []string      `json:"subscriptions"`
	Options       *queryOptions `json:"options"`
}

// queryOptions is the QueryRequestOptions object. Only the fields this
// client drives are modeled; $skipToken is resent verbatim on follow-up
// pages together with the same query and scopes.
type queryOptions struct {
	Top          int    `json:"$top,omitempty"`
	SkipToken    string `json:"$skipToken,omitempty"`
	ResultFormat string `json:"resultFormat"`
}

// queryResponse is the QueryResponse body for objectArray results.
type queryResponse struct {
	Count           int64            `json:"count"`
	TotalRecords    int64            `json:"totalRecords"`
	Data            []map[string]any `json:"data"`
	ResultTruncated string           `json:"resultTruncated"`
	SkipToken       string           `json:"$skipToken"`
}
