import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrRepeatedSkipToken reports that the service (or something in between,
// such as a replaying proxy) returned the same $skipToken the client just
// sent. Following it would loop forever, so pagination stops immediately;
// the partial Report of everything fetched so far accompanies the error.
var ErrRepeatedSkipToken = errors.New("resource graph returned the $skipToken that was just sent")

// GraphErrorDetail is one entry of the error.details array in a Resource
// Graph ErrorResponse body.
type GraphErrorDetail struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// GraphError is a non-200 Resource Graph response mapped from the
// documented ErrorResponse{error{code, message, details[]}} body.
type GraphError struct {
	StatusCode int
	Code       string
	Message    string
	Details    []GraphErrorDetail
}

func (e *GraphError) Error() string {
	return fmt.Sprintf("resource graph: HTTP %d %s: %s", e.StatusCode, e.Code, e.Message)
}

// newGraphError parses the documented error body; if the body is not the
// expected shape the raw text is preserved as the message.
func newGraphError(statusCode int, body []byte) *GraphError {
	var envelope struct {
		Error struct {
			Code    string             `json:"code"`
			Message string             `json:"message"`
			Details []GraphErrorDetail `json:"details"`
		} `json:"error"`
	}
	graphErr := &GraphError{StatusCode: statusCode}
	if err := json.Unmarshal(body, &envelope); err == nil && envelope.Error.Code != "" {
		graphErr.Code = envelope.Error.Code
		graphErr.Message = envelope.Error.Message
		graphErr.Details = envelope.Error.Details
	} else {
		graphErr.Message = string(body)
	}
	return graphErr
}
"}
[tool_call Write] {"file_path":"throttle.go","content":"// Throttling support per the official guidance
// (https://learn.microsoft.com/en-us/azure/governance/resource-graph/concepts/guidance-for-throttled-requests):
// every response carries x-ms-user-quota-remaining (int) and
// x-ms-user-quota-resets-after (hh:mm:ss); when the remaining quota hits 0
// the client must wait out the reset window before the next query.
package rgexport

import (
	"net/http"
	"strconv"
	"strings"
	"time"
)

const (
	headerQuotaRemaining  = "x-ms-user-quota-remaining"
	headerQuotaResetsAfter = "x-ms-user-quota-resets-after"
)

// quotaState is the throttling information carried on a response.
type quotaState struct {
	exhausted  bool
	resetAfter time.Duration
}

// readQuota extracts the user-quota headers. exhausted is set only when the
// remaining-quota header is present, parseable, and zero.
func readQuota(h http.Header) quotaState {
	remaining, err := strconv.Atoi(strings.TrimSpace(h.Get(headerQuotaRemaining)))
	if err != nil || remaining > 0 {
		return quotaState{}
	}
	reset, ok := parseHHMMSS(h.Get(headerQuotaResetsAfter))
	if !ok {
		return quotaState{}
	}
	return quotaState{exhausted: true, resetAfter: reset}
}

// parseHHMMSS parses the documented hh:mm:ss reset duration.
func parseHHMMSS(s string) (time.Duration, bool) {
	parts := strings.Split(strings.TrimSpace(s), ":")
	if len(parts) != 3 {
		return 0, false
	}
	var units [3]int
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 {
			return 0, false
		}
		units[i] = n
	}
	return time.Duration(units[0])*time.Hour +
		time.Duration(units[1])*time.Minute +
		time.Duration(units[2])*time.Second, true
}

// parseRetryAfter reads the Retry-After header of a 429 as whole seconds.
func parseRetryAfter(h http.Header) (time.Duration, bool) {
	seconds, err := strconv.Atoi(strings.TrimSpace(h.Get("Retry-After")))
	if err != nil || seconds < 0 {
		return 0, false
	}
	return time.Duration(seconds) * time.Second, true
}
"}

