import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// Config configures a Client. Zero values fall back to sensible defaults;
// in particular a nil Sleep uses time.Sleep, so tests inject a recorder to
// keep every wait virtual.
type Config struct {
	// BaseURL is the management endpoint, e.g. https://management.azure.com
	// or an httptest server in tests.
	BaseURL string
	// Token is the bearer token sent on every request.
	Token string
	// HTTPClient issues the requests; nil means http.DefaultClient.
	HTTPClient *http.Client
	// Sleep performs every wait (quota resets and 429 Retry-After).
	Sleep func(time.Duration)
	// MaxThrottleRetries bounds how many times a 429 response is retried
	// before the mapped *GraphError is returned.
	MaxThrottleRetries int
}

// Client executes Resource Graph queries with full pagination, quota-aware
// pacing, and bounded throttle retries.
type Client struct {
	baseURL            string
	token              string
	httpClient         *http.Client
	sleep              func(time.Duration)
	maxThrottleRetries int
}

// NewClient builds a Client from cfg.
func NewClient(cfg Config) *Client {
	c := &Client{
		baseURL:            strings.TrimRight(cfg.BaseURL, "/"),
		token:              cfg.Token,
		httpClient:         cfg.HTTPClient,
		sleep:              cfg.Sleep,
		maxThrottleRetries: cfg.MaxThrottleRetries,
	}
	if c.httpClient == nil {
		c.httpClient = http.DefaultClient
	}
	if c.sleep == nil {
		c.sleep = time.Sleep
	}
	return c
}

// postQuery POSTs one page request. A 429 waits out Retry-After and resends
// the byte-identical payload — same $skipToken, nothing rebuilt — at most
// maxThrottleRetries times; any other non-200 is terminal.
func (c *Client) postQuery(ctx context.Context, payload []byte) (*queryResponse, quotaState, error) {
	for attempt := 0; ; attempt++ {
		page, quota, graphErr, err := c.doOnce(ctx, payload)
		if err != nil {
			return nil, quotaState{}, err
		}
		if graphErr == nil {
			return page, quota, nil
		}
		if graphErr.StatusCode != http.StatusTooManyRequests || attempt >= c.maxThrottleRetries {
			return nil, quotaState{}, graphErr
		}
		if wait, ok := parseRetryAfter(graphErr.retryAfter); ok {
			c.sleep(wait)
		}
	}
}

// doOnce performs a single HTTP exchange. A non-200 comes back as a
// *GraphError value (not the error return) so postQuery can decide whether
// to retry it.
func (c *Client) doOnce(ctx context.Context, payload []byte) (*queryResponse, quotaState, *graphHTTPError, error) {
	url := c.baseURL + resourcesPath + "?api-version=" + apiVersion
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(payload))
	if err != nil {
		return nil, quotaState{}, nil, fmt.Errorf("building request: %w", err)
	}
	req.Header.Set("Authorization", "Bearer "+c.token)
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, quotaState{}, nil, fmt.Errorf("posting query: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, quotaState{}, nil, fmt.Errorf("reading response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, quotaState{}, &graphHTTPError{
			GraphError: newGraphError(resp.StatusCode, body),
			retryAfter: resp.Header,
		}, nil
	}

	var page queryResponse
	if err := json.Unmarshal(body, &page); err != nil {
		return nil, quotaState{}, nil, fmt.Errorf("decoding query response: %w", err)
	}
	return &page, readQuota(resp.Header), nil, nil
}

// graphHTTPError pairs the mapped *GraphError with the response headers the
// retry logic needs (Retry-After).
type graphHTTPError struct {
	*GraphError
	retryAfter http.Header
}
"}

