import (
	"context"
	"encoding/json"
	"fmt"
)

// Query describes one Resource Graph query to run to completion.
type Query struct {
	// Query is the KQL resources query.
	Query string
	// Subscriptions scopes the query; resent unchanged on every page.
	Subscriptions []string
	// PageSize sets options.$top when > 0; zero accepts the service default.
	PageSize int
}

// Report is the outcome of a fully paginated query.
type Report struct {
	// Rows holds every objectArray row across all pages, in order.
	Rows []map[string]any
	// TotalRecords is the service-reported total matching the query.
	TotalRecords int64
	// Truncated is true if any page reported resultTruncated "true"
	// (a string enum on the wire, not a boolean).
	Truncated bool
	// Pages counts the successful page responses consumed.
	Pages int
	// QuotaWaits counts quota-reset waits taken between pages; 429
	// Retry-After waits are not included.
	QuotaWaits int
}

// QueryAll runs q and follows $skipToken continuations until the service
// stops returning one, resending the same query and scopes each time. An
// empty data page that still carries a token is not the end. If a response
// echoes the token that was just sent, QueryAll stops and returns the
// partial Report together with ErrRepeatedSkipToken.
func (c *Client) QueryAll(ctx context.Context, q Query) (*Report, error) {
	report := &Report{}
	sentToken := ""
	for {
		opts := &queryOptions{ResultFormat: resultFormatObjectArray}
		if q.PageSize > 0 {
			opts.Top = q.PageSize
		}
		opts.SkipToken = sentToken
		payload, err := json.Marshal(queryRequest{
			Query:         q.Query,
			Subscriptions: q.Subscriptions,
			Options:       opts,
		})
		if err != nil {
			return nil, fmt.Errorf("encoding query request: %w", err)
		}

		page, quota, err := c.postQuery(ctx, payload)
		if err != nil {
			return nil, err
		}
		report.Rows = append(report.Rows, page.Data...)
		report.Pages++
		report.TotalRecords = page.TotalRecords
		if page.ResultTruncated == resultTruncatedTrue {
			report.Truncated = true
		}

		if page.SkipToken == "" {
			return report, nil
		}
		if page.SkipToken == sentToken {
			return report, fmt.Errorf("%w: %q", ErrRepeatedSkipToken, sentToken)
		}
		// Another page is coming: if this response spent the last of the
		// user quota, wait out the documented reset window first.
		if quota.exhausted {
			c.sleep(quota.resetAfter)
			report.QuotaWaits++
		}
		sentToken = page.SkipToken
	}
}
"}
